269	                if description.is_empty() {
270	                    format!("{}'s LTB trigger", card_name(*card_id))
271	                } else {
272	                    format!("{}'s LTB trigger ({})", card_name(*card_id), description)
273	                }
274	            }
275	            PendingTrigger::AttacksTrigger { card_id, description, .. }
276	            | PendingTrigger::AttackWatch { watcher_card_id: card_id, description, .. } => {
277	                if description.is_empty() {
278	                    format!("{}'s attack trigger", card_name(*card_id))
279	                } else {
280	                    format!("{}'s attack trigger ({})", card_name(*card_id), description)
281	                }
282	            }
